const body = $input.first().json;
const text = String(body.text || body.event?.resource?.text || '').trim();
const openId = String(body.open_id || '');
// Spike：知识库未就绪时返回说明。上线请在本节点前插入 AI Agent，
// 工具仅允许 search（bitable/知识库 HTTP），禁止 create/update record。
let reply;
if (!text) {
  reply = '请说明要查的供应商或资源，例如：查供应商 德清某某茶歇';
} else {
  reply = [
    '【查询占位，尚未接知识库】',
    '问题：' + text,
    '请在 n8n 中于 Webhook 与本节点之间加入 AI Agent + 只读检索工具。',
    '录入请用「添加供应商」，不要在本工作流写表。'
  ].join('\n');
}
return [{ json: { reply, open_id: openId, action: 'search' } }];
